<script setup>
import { computed, ref } from 'vue'
import { ArrowDownLeft, ArrowUpRight, Coins, LockKeyhole } from '@lucide/vue'
import { useAppStore } from '../stores/app'
import { dateLabel, timeLabel } from '../features/timebank/format'
const store = useAppStore()
const filter = ref('')
const labels = { Ajuste: 'Ajuste', Retencion: 'Retención', Liberacion: 'Liberación', Consumo: 'Intercambio aprendido', Recompensa: 'Habilidad compartida', BonoInicial: 'Bono inicial', Transferencia: 'Transferencia', Penalizacion: 'Penalización' }
const movements = computed(() => store.myMovements.filter((row) => !filter.value || row.tipo === filter.value))
const difference = (row) => row.saldo_posterior - row.saldo_anterior
</script>
<template>
  <header class="workspace-header"><div><h1>Mis créditos</h1><p>El tiempo que compartes, el tiempo que puedes aprender.</p></div><span class="subtle-label">1 crédito equivale a 15 minutos</span></header>
  <section class="credit-account" aria-label="Resumen de tu cuenta"><div class="credit-main"><Coins :size="28" aria-hidden="true" /><span>Disponibles</span><strong>{{ store.account.disponibles }} <small>créditos</small></strong><p>Para solicitar tiempo de aprendizaje.</p></div><div class="credit-secondary"><div><span><LockKeyhole :size="17" />Retenidos</span><strong>{{ store.account.creditos_retenidos }}</strong><p>Asignados a reservas confirmadas.</p></div><div><span>Saldo total</span><strong>{{ store.account.saldo }}</strong><p>Incluye los créditos retenidos.</p></div></div></section>
  <div class="credits-layout"><section aria-labelledby="movements-title"><header class="section-heading"><div><h2 id="movements-title">Movimientos</h2><p role="status">{{ movements.length }} registros</p></div><label class="select-wrap"><span class="sr-only">Filtrar movimientos por tipo</span><select v-model="filter"><option value="">Todos los movimientos</option><option v-for="type in [...new Set(store.myMovements.map(row => row.tipo))]" :key="type" :value="type">{{ labels[type] ?? type }}</option></select></label></header><div class="movement-list"><article v-for="row in movements" :key="row.id_movimiento" class="movement-row"><span class="movement-icon" :class="{incoming: difference(row) > 0}"><ArrowDownLeft v-if="difference(row) > 0" :size="21" /><LockKeyhole v-else-if="row.tipo === 'Retencion'" :size="19" /><ArrowUpRight v-else :size="21" /></span><div><h3>{{ labels[row.tipo] ?? row.tipo }}</h3><p>{{ row.descripcion }}</p><small>{{ dateLabel(row.created_at) }}, {{ timeLabel(row.created_at) }}</small></div><div class="movement-amount"><strong :class="{incoming: difference(row) > 0}">{{ difference(row) > 0 ? '+' : '' }}{{ difference(row) || row.cantidad }} <small>cr.</small></strong><span>{{ row.tipo === 'Retencion' ? 'Retenidos' : row.tipo === 'Liberacion' ? 'Liberados' : `Saldo: ${row.saldo_posterior}` }}</span></div></article><div v-if="!movements.length" class="empty-state"><Coins :size="28" /><h3>No hay movimientos de este tipo</h3><p>Prueba con otro filtro.</p></div></div></section><aside class="credit-explanation"><h2>¿Cómo circulan?</h2><ol><li><strong>Solicitas</strong><p>Enviar una solicitud no descuenta créditos.</p></li><li><strong>Se reserva el tiempo</strong><p>Al aceptar, los créditos quedan retenidos.</p></li><li><strong>Ambos confirman</strong><p>Después del intercambio, se transfieren al estudiante que compartió su habilidad.</p></li></ol></aside></div>
</template>
